import { useParams } from "react-router-dom";
import { useEffect, useState } from "react";
import axios from "axios";

export default function Perfil() {
  const { id } = useParams();
  const [usuario, setUsuario] = useState(null);
  const [erro, setErro] = useState("");

  useEffect(() => {
    axios
      .get(`http://localhost:3001/usuarios/${id}`)
      .then((res) => setUsuario(res.data))
      .catch((err) => {
        console.error("Erro ao buscar usuário:", err);
        setErro("Usuário não encontrado.");
      });
  }, [id]);

  if (erro) return <p className="text-danger">{erro}</p>;
  if (!usuario) return <p>Carregando perfil...</p>;

  return (
    <div className="card">
      <div className="card-body">
        <h3 className="card-title">{usuario.nome}</h3>
        <p className="card-text"><strong>Idade:</strong> {usuario.idade}</p>
        <p className="card-text"><strong>Endereço:</strong> {usuario.rua}, {usuario.bairro}, {usuario.estado}</p>
        <p className="card-text"><strong>Biografia:</strong> {usuario.biografia}</p>
        {usuario.imagem && (
          <img
            src={`http://localhost:3001${usuario.imagem}`}
            alt="Foto do usuário"
            className="img-thumbnail mt-3"
            width="200"
          />
        )}
      </div>
    </div>
  );
}
